// รวมรายชื่อบทความที่มีอยู่แล้วทั้งหมด (ทั้งของเก่าที่ hardcode ไว้ และของที่ AI เขียนไปแล้ว)

// บทความเดิมในเว็บ — อัปเดตลิสต์นี้ถ้ามีการเพิ่มบทความด้วยมือ
const manualTopics = [
  'รับซื้อทองพัทยา ร้านไหนดี',
  'ขายทองไม่มีใบเสร็จ ขายได้ไหม',
  'วิธีคำนวณราคาขายทองเก่า',
  'ทองขาด ทองหัก ชำรุด รับซื้อไหม',
  'ขายทองที่ไหนให้ราคาสูงที่สุดในพัทยา',
  'มีทองเก่า ทองหัก ขายที่ไหนดี',
  'ตรวจสอบทองฟรี พัทยา',
  'หลอมทองพัทยาที่ไหนดี',
  'เจาะลึกขั้นตอนหลอมทองพัทยา',
  'หลอมทองคืออะไร',
  'วิธีตรวจสอบทองแท้ด้วยตัวเอง 5 วิธี',
  'ราคาทองวันนี้ แนวโน้มราคาทอง',
  'ทองเค 9K 14K 18K ขายได้ไหม',
];

// รายชื่อไฟล์จาก GitHub (ถ้าโฟลเดอร์ยังไม่มี จะได้ 404 = ถือว่าว่าง)
let autoSlugs = [];
const items = $input.all();
for (const item of items) {
  const d = item.json;
  if (Array.isArray(d)) {
    autoSlugs = d.filter(f => f.name && f.name.endsWith('.json')).map(f => f.name.replace('.json',''));
  } else if (d.name && d.name.endsWith('.json')) {
    autoSlugs.push(d.name.replace('.json',''));
  }
}

const cfg = $('ตั้งค่า GitHub').first().json;

return [{
  json: {
    ...cfg,
    existingSlugs: autoSlugs,
    existingTopicsText: manualTopics.join('\n- '),
    existingSlugsText: autoSlugs.length ? autoSlugs.join(', ') : '(ยังไม่มี)',
    today: new Date().toISOString().slice(0,10),
  }
}];

// ============================================================
// ด่านตรวจก่อนขึ้นเว็บ — กัน AI ส่งของเสียขึ้นไปทำเว็บพัง
// ============================================================
const cfg = $('รวมหัวข้อที่เขียนไปแล้ว').first().json;
const raw = $input.first().json;

// 1) ดึงข้อความจาก AI (รองรับหลายรูปแบบ output)
let text = raw.text ?? raw.output ?? raw.response ?? raw.data ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);

// 2) ตัด ```json ``` ที่ AI ชอบใส่มา
text = text.trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();

// 3) เผื่อมีข้อความนำหน้า — ตัดเอาเฉพาะก้อน JSON
const first = text.indexOf('{');
const last = text.lastIndexOf('}');
if (first === -1 || last === -1) {
  throw new Error('AI ไม่ได้ส่ง JSON กลับมา — ได้: ' + text.slice(0, 200));
}
text = text.slice(first, last + 1);

// 4) แปลงเป็น object
let a;
try {
  a = JSON.parse(text);
} catch (e) {
  throw new Error('JSON ที่ AI ส่งมาผิดรูปแบบ: ' + e.message);
}

// 5) ตรวจฟิลด์ที่ขาดไม่ได้
for (const k of ['slug','title','description','sections']) {
  if (!a[k]) throw new Error('ขาดฟิลด์: ' + k);
}

// 6) slug ต้องเป็น a-z 0-9 - เท่านั้น
if (!/^[a-z0-9-]+$/.test(a.slug)) {
  throw new Error('slug ผิดรูปแบบ: ' + a.slug);
}

// 7) ห้ามซ้ำกับที่มีอยู่แล้ว
if ((cfg.existingSlugs || []).includes(a.slug)) {
  throw new Error('slug ซ้ำกับบทความเดิม: ' + a.slug);
}

// 8) sections ต้องถูกชนิด และมีเนื้อหาพอ
const ALLOWED = ['summary','h2','h3','p','ul','ol','quote'];
if (!Array.isArray(a.sections) || a.sections.length < 8) {
  throw new Error('sections สั้นเกินไป (' + (a.sections||[]).length + ' บล็อก)');
}
for (const s of a.sections) {
  if (!ALLOWED.includes(s?.type)) throw new Error('section type ไม่รองรับ: ' + s?.type);
  if (typeof s.text !== 'string' && !Array.isArray(s.items)) {
    throw new Error('section ไม่มีเนื้อหา: ' + s.type);
  }
}

// 9) หมวดรูปต้องเป็นหมวดที่มีจริง (ระบบจะสลับรูปในหมวดให้เอง)
const OK_THEME = ['lomthong','truat-thong','rap-sue-thong','thong-kao','ran-thong','krob-phra','nalika','brandname'];
if (!OK_THEME.includes(a.coverTheme)) a.coverTheme = 'rap-sue-thong';
delete a.fallbackImage; // ไม่ต้องระบุ path เอง ให้เว็บเลือกจากคลังรูป

// 10) บังคับวันที่เป็นวันนี้เสมอ
a.date = cfg.today;

// 11) โหมดเผยแพร่:
//     true  = ขึ้นเว็บทันที
//     false = ขึ้นเป็นร่าง (ไม่แสดงบนเว็บ) ต้องมาแก้เป็น true เอง
a.published = true;

const content = JSON.stringify(a, null, 2);

return [{
  json: {
    ...cfg,
    slug: a.slug,
    title: a.title,
    filePath: 'content/articles/' + a.slug + '.json',
    commitMessage: 'บทความใหม่: ' + a.title,
    fileContentBase64: Buffer.from(content, 'utf8').toString('base64'),
  }
}];

const c = $('ตรวจสอบก่อนขึ้นเว็บ').first().json;
return [{ json: {
  สถานะ: 'สำเร็จ',
  บทความ: c.title,
  ลิงก์: 'https://หลอมทองพัทยา.com/blog/' + c.slug,
  ไฟล์: c.filePath,
  หมายเหตุ: 'Vercel กำลัง deploy — รอ 1-2 นาทีแล้วเปิดลิงก์ได้',
}}];
